'use strict';
const $$=(s,r=document)=>[...r.querySelectorAll(s)],$=(s,r=document)=>r.querySelector(s);
const nav=$('.primary-nav'),menu=$('.menu-toggle');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
$$('.nav-group').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)$$('.nav-group').forEach(o=>{if(o!==d)o.open=false})}));
document.addEventListener('click',e=>{if(!e.target.closest('.site-header'))$$('.nav-group').forEach(d=>d.open=false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const group=document.activeElement?.closest('.nav-group'),mobile=menu?.getAttribute('aria-expanded')==='true'&&nav?.contains(document.activeElement);$$('.nav-group').forEach(d=>d.open=false);nav?.classList.remove('open');menu?.setAttribute('aria-expanded','false');if(mobile)menu.focus();else if(group)group.querySelector('summary')?.focus()}});
$('.back-top')?.addEventListener('click',()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'}));
const dialog=$('#search-dialog'),search=$('#site-search'),results=$('#search-results');let searchIndex=null;
async function runSearch(){if(!searchIndex){try{searchIndex=await fetch(BMDI18n.isZh?'assets/search-index-zh.json':'assets/search-index.json').then(r=>r.json())}catch{results.textContent=BMDI18n.t('Search is unavailable. Browse the page links in the navigation.');return}}const q=search.value.trim().toLocaleLowerCase();results.replaceChildren();const found=searchIndex.filter(x=>!q||(x.title+' '+x.text).toLocaleLowerCase().includes(q)).slice(0,20);if(!found.length){results.textContent=BMDI18n.t('No matches. Try a faculty name, curriculum year, or resource keyword.');return}for(const item of found){const a=document.createElement('a');a.className='search-result';a.href=item.url;const b=document.createElement('b');b.textContent=item.title;const s=document.createElement('small');s.textContent=item.category;a.append(b,s);results.append(a)}}
$$('[data-search-open]').forEach(b=>b.addEventListener('click',()=>{dialog.showModal();search.focus();runSearch()}));$('[data-search-close]')?.addEventListener('click',()=>dialog.close());search?.addEventListener('input',runSearch);dialog?.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
$$('[data-filter-scope]').forEach(scope=>{
 const input=$('[data-filter-input]',scope),buttons=$$('[data-filter]',scope),items=$$('[data-filter-item]',scope).filter(el=>!el.parentElement.closest('[data-filter-item]'));let category=scope.dataset.filterDefault||'all';
 function filter(){const q=(input?.value||'').toLocaleLowerCase().trim();let count=0;items.forEach(item=>{const categoryMatch=category==='all'||item.dataset.category===category||(category==='published'&&item.dataset.category!=='archive');const show=(!q||(item.textContent+' '+(item.dataset.searchAlias||'')).toLocaleLowerCase().includes(q))&&categoryMatch;item.hidden=!show;if(show)count++});const empty=$('.empty',scope);if(empty)empty.hidden=count!==0}
 input?.addEventListener('input',filter);buttons.forEach(button=>button.addEventListener('click',()=>{category=button.dataset.filter;buttons.forEach(other=>{other.classList.toggle('active',other===button);other.setAttribute('aria-pressed',String(other===button))});filter()}));filter();
});
const learning=[[BMDI18n.t('Operations Management'),BMDI18n.t('Understand operations, industries, and management in practice.')],[BMDI18n.t('Smart Business'),BMDI18n.t('Use data and digital tools for business decisions.')],[BMDI18n.t('Sustainable Innovation'),BMDI18n.t('Connect social innovation with sustainable management.')],[BMDI18n.t('Culinary Management'),BMDI18n.t('Combine food, service, and management practice.')]];
const lTabs=$$('[data-learning-tab]');function chooseLearning(i,focus=false){lTabs.forEach((t,j)=>{t.setAttribute('aria-selected',String(j===i));t.tabIndex=j===i?0:-1});$('#learning-title').textContent=learning[i][0];$('#learning-description').textContent=learning[i][1];$('#learning-panel').setAttribute('aria-labelledby',lTabs[i].id);if(focus){lTabs[i].focus();history.replaceState(null,'','#'+lTabs[i].id)}}lTabs.forEach((t,i)=>{t.addEventListener('click',()=>{chooseLearning(i);history.replaceState(null,'','#'+t.id)});t.addEventListener('keydown',e=>{let n;if(['ArrowDown','ArrowRight'].includes(e.key))n=(i+1)%lTabs.length;else if(['ArrowUp','ArrowLeft'].includes(e.key))n=(i+lTabs.length-1)%lTabs.length;else if(e.key===BMDI18n.t('Home'))n=0;else if(e.key==='End')n=lTabs.length-1;else return;e.preventDefault();chooseLearning(n,true)})});
function learningFromHash(){const i=lTabs.findIndex(tab=>'#'+tab.id===location.hash);if(i>=0)chooseLearning(i)}
learningFromHash();addEventListener('hashchange',learningFromHash);
const milestones=[['2000',BMDI18n.t('The accounting roots'),BMDI18n.t('A four-year Accounting program was introduced, laying the foundation for the department’s academic journey.')],['2004',BMDI18n.t('Accounting meets technology'),BMDI18n.t('The department was renamed Accounting Information to prepare accounting professionals for a changing technological environment.')],['2013',BMDI18n.t('A new direction'),BMDI18n.t('Accounting Information was renamed Marketing and Distribution Management.')],['2023',BMDI18n.t('Broader horizons'),BMDI18n.t('Marketing and Distribution Management was renamed Business Management, reflecting an interdisciplinary direction.')],['2024',BMDI18n.t('A new chapter at TCU'),BMDI18n.t('Tzu Chi University of Science and Technology merged with Tzu Chi University on August 1, 2024.')]];
const yearTabs=$$('[data-year]');function chooseYear(i,focus=false){yearTabs.forEach((t,j)=>{t.setAttribute('aria-selected',String(i===j));t.tabIndex=i===j?0:-1});$('#history-year').textContent=milestones[i][0];$('#history-title').textContent=milestones[i][1];$('#history-description').textContent=milestones[i][2];$('#history-panel').setAttribute('aria-labelledby',yearTabs[i].id);if(focus)yearTabs[i].focus()}yearTabs.forEach((t,i)=>{t.addEventListener('click',()=>chooseYear(i));t.addEventListener('keydown',e=>{let n;if(['ArrowRight','ArrowDown'].includes(e.key))n=(i+1)%5;else if(['ArrowLeft','ArrowUp'].includes(e.key))n=(i+4)%5;else if(e.key===BMDI18n.t('Home'))n=0;else if(e.key==='End')n=4;else return;e.preventDefault();chooseYear(n,true)})});
const calendar=$('#calendar');
if(calendar){
 const events=JSON.parse($('#calendar-data').textContent),config=JSON.parse($('#calendar-config').textContent),months=BMDCalendarDate.months(config),format=new Intl.DateTimeFormat(BMDI18n.locale,{month:'long',year:'numeric'});
 let current=BMDCalendarDate.initialIndex(months),selected=null;
 const key=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
 function render(){
  const month=months[current],first=key(month),last=key(new Date(month.getFullYear(),month.getMonth()+1,0)),today=BMDCalendarDate.parts(),todayKey=`${today.year}-${String(today.month).padStart(2,'0')}-${String(today.day).padStart(2,'0')}`;
  $('#calendar-month').textContent=format.format(month);$('#cal-previous').disabled=current===0;$('#cal-next').disabled=current===months.length-1;
  const days=$('#calendar-days');days.replaceChildren();const start=new Date(month.getFullYear(),month.getMonth(),1-(month.getDay()+6)%7);
  for(let i=0;i<42;i++){
   const d=new Date(start);d.setDate(start.getDate()+i);const k=key(d),button=document.createElement('button');button.type='button';button.textContent=String(d.getDate());button.className='day';button.disabled=d.getMonth()!==month.getMonth();
   if(button.disabled)button.classList.add('outside');const has=events.some(e=>e.start<=k&&e.end>=k);if(has)button.classList.add('event');if(selected===k)button.classList.add('selected');if(k===todayKey){button.classList.add('today');button.setAttribute('aria-current','date')}
   button.setAttribute('aria-pressed',String(selected===k));button.setAttribute('aria-label',new Intl.DateTimeFormat(BMDI18n.locale,{dateStyle:'full'}).format(d)+(has?BMDI18n.t(', event scheduled'):''));button.addEventListener('click',()=>{selected=selected===k?null:k;render()});days.append(button);
  }
  const chosen=events.filter(e=>selected?(e.start<=selected&&e.end>=selected):(e.start<=last&&e.end>=first)),list=$('#calendar-events');list.replaceChildren();$('#event-list-title').textContent=selected?new Intl.DateTimeFormat(BMDI18n.locale,{dateStyle:'long'}).format(new Date(selected+'T12:00:00')):format.format(month);
  if(!chosen.length){const p=document.createElement('p');p.className='empty';p.textContent=BMDI18n.t('No selected dates listed for this selection. Consult the full university calendar.');list.append(p)}
  const completed=chosen.filter(event=>BMDCalendarDate.eventState(event,todayKey)==='completed');
  const active=chosen.filter(event=>BMDCalendarDate.eventState(event,todayKey)!=='completed').sort((a,b)=>a.start.localeCompare(b.start));
  function eventCard(event){const article=document.createElement('article');article.className='event-card';const state=BMDCalendarDate.eventState(event,todayKey);article.dataset.eventState=state;const badge=document.createElement('span');badge.className='event-state';badge.textContent=state==='completed'?BMDI18n.t('Completed'):state==='ongoing'?BMDI18n.t('In progress'):BMDI18n.t('Upcoming');const small=document.createElement('small');small.textContent=event.start+(event.end!==event.start?' — '+event.end:'');const h=document.createElement('h3');h.textContent=event.title;const p=document.createElement('p');p.textContent=event.description;article.append(badge,document.createElement('br'),small,h,p);return article}
  active.forEach(event=>list.append(eventCard(event)));
  if(completed.length){if(selected){completed.forEach(event=>list.append(eventCard(event)))}else{const details=document.createElement('details');details.className='calendar-completed';const summary=document.createElement('summary');summary.textContent=BMDI18n.t('Completed dates');details.append(summary);completed.forEach(event=>details.append(eventCard(event)));list.append(details)}}
 }
 $('#cal-previous').addEventListener('click',()=>{if(current>0){current--;selected=null;render()}});$('#cal-next').addEventListener('click',()=>{if(current<months.length-1){current++;selected=null;render()}});
 let observed=BMDCalendarDate.parts();
 function refreshDate(){const now=BMDCalendarDate.parts();if(now.year!==observed.year||now.month!==observed.month){current=BMDCalendarDate.initialIndex(months);selected=null;observed=now;render()}else if(now.day!==observed.day){observed=now;render()}}
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshDate()});setInterval(refreshDate,60000);render();
}
